import { Request, Response, NextFunction } from "express";
import { CreateUserUseCase } from "../application/create-user-use-case";

export class UserController {
  public constructor(private readonly createUser: CreateUserUseCase) {}

  public create = async (request: Request, response: Response, next: NextFunction): Promise<void> => {
    try {
      const name = this.stringField(request.body, "name");
      response.status(201).json(await this.createUser.execute({ name }));
    } catch (error) { next(error); }
  };

  private stringField(body: unknown, field: string): string {
    return typeof body === "object" && body !== null && typeof (body as Record<string, unknown>)[field] === "string"
      ? (body as Record<string, string>)[field]
      : "";
  }
}

